<?php
require '/app/harness.php';require '/app/driver-functions.php';
// PHP-WASM lacks POSIX process metadata. Only this OS boundary is supplied.
if(!function_exists('posix_geteuid')){function posix_geteuid(){return 0;}}
function rejectGuard($fn,$pattern){try{$fn();}catch(Throwable$e){if(!preg_match($pattern,$e->getMessage()))throw new RuntimeException('Wrong refusal: '.$e->getMessage());return;}throw new RuntimeException('Unsafe driver guard accepted');}
function driverFixture(){
 global $dataset,$guid,$base,$stateFile,$state,$stateHandle;
 if(is_resource($stateHandle??null)){flock($stateHandle,LOCK_UN);fclose($stateHandle);}$stateHandle=null;
 $dataset='cache/zfs-director-acceptance-20261018T120000-'.bin2hex(random_bytes(3));$guid='123';$base='/mnt/'.$dataset;$stage='/tmp/zfs-director-update-20261018T120000-'.bin2hex(random_bytes(3));
 @mkdir('/mnt/cache',0755,true);mkdir($base,0700);@mkdir('/tmp',01777);chmod('/tmp',01777);mkdir($stage,0700);$stateFile=$stage.'/acceptance-state.json';$state=['dataset'=>$dataset,'guid'=>$guid,'checks'=>[],'jobs'=>[],'objects'=>[$dataset=>$guid]];
 chmod('/',0755);@mkdir('/proc/self',0755,true);file_put_contents('/proc/self/mountinfo',"1 0 0:1 / / rw - rootfs rootfs rw\n2 1 0:2 / $base rw - zfs $dataset rw\n");
}
function expectBase($mountpoint=null,$mounted='yes'){
 global $dataset,$guid,$base;
 expectProcess('zfs',['list','-H','-p','-o','name,type,guid','-t','filesystem,volume,snapshot',$dataset],"$dataset\tfilesystem\t$guid");
 expectProcess('zfs',['get','-H','-p','-o','property,value','mountpoint,mounted,readonly',$dataset],"mountpoint\t".($mountpoint??$base)."\nmounted\t$mounted\nreadonly\toff");
}
check('GUID and quota cannot authorize wrong configured mountpoint',function(){driverFixture();expectBase('/');rejectGuard(fn()=>ownIdentity(),'/mountpoint|mounted/');});
check('valid ZFS record without exact live mount cannot authorize host path',function(){driverFixture();expectBase();file_put_contents('/proc/self/mountinfo',"1 0 0:1 / / rw - rootfs rootfs rw\n");rejectGuard(fn()=>ownIdentity(),'/live.*mount/i');});
check('base symlink cannot authorize root chown even when GUID is correct',function(){driverFixture();global $base;rmdir($base);symlink('/',$base);rejectGuard(fn()=>ownIdentity(),'/symbolic|canonical|symlink/i');same(0,count($GLOBALS['test_calls']));});
