check('state parent ownership and mode are required before creation',function(){driverFixture();global $stateFile;chmod(dirname($stateFile),0777);rejectGuard(fn()=>acceptanceOpenState(true),'/private|0700/');same(false,file_exists($stateFile));});
check('symlink and hardlinked state cannot truncate another file',function(){driverFixture();global $stateFile;$victim=dirname($stateFile).'/victim';file_put_contents($victim,'KEEP');chmod($victim,0600);symlink($victim,$stateFile);rejectGuard(fn()=>acceptanceOpenState(true),'/regular|symlink/');same('KEEP',file_get_contents($victim));unlink($stateFile);/* PHP-WASM cannot create hardlinks; exercise the real metadata rejection with a native-style nlink value. */$linked=lstat($victim);$linked['nlink']=2;rejectGuard(fn()=>acceptanceStateStat($linked),'/link|regular/');same('KEEP',file_get_contents($victim));});
check('valid state is opened once with exclusive lock and saves exact bytes',function(){driverFixture();global $stateFile,$stateHandle,$state;acceptanceOpenState(true);$state['marker']='synthetic';saveAcceptance();same('synthetic',json_decode(file_get_contents($stateFile),true)['marker']);$s=fstat($stateHandle);same(0600,$s['mode']&07777);same(1,$s['nlink']);});
check('state replacement after open cannot redirect truncation',function(){driverFixture();global $stateFile,$state;acceptanceOpenState(true);saveAcceptance();$old=$stateFile.'.retained';rename($stateFile,$old);$victim=dirname($stateFile).'/untouched';file_put_contents($victim,'KEEP');chmod($victim,0600);symlink($victim,$stateFile);rejectGuard(fn()=>saveAcceptance(),'/regular|symlink|identity/');same('KEEP',file_get_contents($victim));same(true,is_file($old));});
check('existing state with permissive mode is never repaired or truncated',function(){driverFixture();global $stateFile;file_put_contents($stateFile,'KEEP');chmod($stateFile,0644);rejectGuard(fn()=>acceptanceOpenState(true),'/regular|0600/');same('KEEP',file_get_contents($stateFile));same(0644,fileperms($stateFile)&07777);});
check('replay is rejected after started marker even before the first PASS',function(){driverFixture();global $state;$state['phase']='started';rejectGuard(fn()=>acceptanceFreshRun(),'/replay|already|started/i');});
check('replay refusal preserves existing state bytes and performs no operation',function(){driverFixture();global $dataset,$guid,$stateFile,$state;$state['phase']='started';file_put_contents($stateFile,json_encode($state));chmod($stateFile,0600);$before=file_get_contents($stateFile);putenv('ZFSD_TEST_DATASET='.$dataset);putenv('ZFSD_TEST_GUID='.$guid);putenv('ZFSD_TEST_STATE='.$stateFile);rejectGuard(fn()=>runAcceptance('operations'),'/replay|already|started/i');same($before,file_get_contents($stateFile));same([], $GLOBALS['test_calls']);});
check('foreign state refusal cannot rewrite the foreign record',function(){driverFixture();global $dataset,$guid,$stateFile,$state;$state['guid']='999';file_put_contents($stateFile,json_encode($state));chmod($stateFile,0600);$before=file_get_contents($stateFile);putenv('ZFSD_TEST_DATASET='.$dataset);putenv('ZFSD_TEST_GUID='.$guid);putenv('ZFSD_TEST_STATE='.$stateFile);rejectGuard(fn()=>runAcceptance('operations'),'/identity/');same($before,file_get_contents($stateFile));same([], $GLOBALS['test_calls']);});
check('backend ACL verification rejects unknown instead of accepting status presence',function(){rejectGuard(fn()=>acceptanceMetadata(['_acl'=>['status'=>'unknown','reason'=>'not verified'],'_usage'=>[]],false),'/ACL.*unknown.*not verified/');});
check('backend ACL summary checks parsed default UID and mask without exposing service paths',function(){$properties=['_acl'=>['status'=>'known','type'=>'posix','has_default'=>true,'entries'=>[['scope'=>'default','tag'=>'user','id'=>'1001','permissions'=>'rwx','effective'=>'rwx'],['scope'=>'default','tag'=>'mask','id'=>null,'permissions'=>'rwx','effective'=>'rwx']]],'_usage'=>[]];foreach(['smb','nfs','docker','vm']as$key)$properties['_usage'][$key]=['status'=>'unknown','entries'=>[['path'=>'/private-config-path','name'=>'private-service']]];$summary=acceptanceMetadata($properties,true);same('known',$summary['acl']['status']);same(1,$summary['usage']['docker']['entries']);same(false,str_contains(json_encode($summary),'private'));$properties['_acl']['entries'][1]['permissions']='r-x';rejectGuard(fn()=>acceptanceMetadata($properties,true),'/default.*1001|mask/');});
